// Pure logic for status-keeper: no node: imports, so the browser page can use it too.
export const DEFAULTS = { intervalSec: 60, failAfter: 2, timeoutMs: 10_000, graceSec: 60 };
export const KEEP_DAYS = 90;
// Expiry watchers: "tls" (certificate of host:port) and "domain" (registration, via RDAP).
// They check slowly, fail on the first miss, and warn at fixed days-left thresholds.
export const EXPIRY_TYPES = ["tls", "domain"];
export const EXPIRY_DEFAULTS = { intervalSec: 21_600, failAfter: 1, timeoutMs: 10_000, warnDays: [30, 14, 7, 3, 1] };
const RECENT = 60, MAX_INCIDENTS = 200;
export const IMPACTS = ["minor", "major"];
export const INCIDENT_STATUSES = ["investigating", "identified", "monitoring", "resolved"];

export const newState = () => ({ v: 1, monitors: {}, incidents: [], maintenance: [] });
export const dayKey = (ms) => new Date(ms).toISOString().slice(0, 10);

function mon(state, id) {
  return (state.monitors[id] ||= { id, status: "unknown", streakFail: 0, streakOk: 0, firstFailAt: null, lastCheckAt: null, lastMs: null, lastError: null, lastPingAt: null, days: {}, recent: [] });
}

export function inMaintenance(state, monitorId, now) {
  return state.maintenance.some((m) => m.startsAt <= now && now < m.endsAt && (!m.monitors.length || m.monitors.includes(monitorId)));
}

const openAutoIncident = (state, id) => state.incidents.find((i) => i.auto && !i.resolvedAt && i.monitors.includes(id));

function pushIncident(state, inc) {
  state.incidents.unshift(inc);
  if (state.incidents.length > MAX_INCIDENTS) state.incidents.length = MAX_INCIDENTS;
}

// Fold one check result into the state. Returns events for the caller to alert on.
// result: {ok:boolean, ms?:number, error?:string}
export function recordCheck(state, def, result, now) {
  const m = mon(state, def.id);
  const failAfter = def.failAfter ?? DEFAULTS.failAfter;
  const events = [];
  m.lastCheckAt = now;
  m.lastMs = result.ms ?? null;
  m.lastError = result.ok ? null : String(result.error || "check failed").slice(0, 200);
  const planned = inMaintenance(state, def.id, now);
  const d = (m.days[dayKey(now)] ||= { ok: 0, total: 0 });
  // A check during planned maintenance is not counted against uptime.
  if (!planned) { d.total++; if (result.ok) d.ok++; }
  m.recent.push({ at: now, ok: result.ok, ms: result.ms ?? null });
  if (m.recent.length > RECENT) m.recent.splice(0, m.recent.length - RECENT);
  for (const k of Object.keys(m.days).sort().slice(0, -KEEP_DAYS)) delete m.days[k];

  if (result.ok) {
    m.streakFail = 0; m.streakOk++; m.firstFailAt = null;
    if (m.status === "down") {
      const inc = openAutoIncident(state, def.id);
      if (inc) { inc.status = "resolved"; inc.resolvedAt = now; inc.updates.push({ at: now, status: "resolved", message: "Checks are passing again." }); events.push({ type: "recovered", monitor: def, incident: inc, downMs: now - inc.startedAt }); }
    }
    m.status = "up";
  } else {
    if (!m.streakFail) m.firstFailAt = now;
    m.streakFail++; m.streakOk = 0;
    if (m.streakFail >= failAfter && m.status !== "down" && !planned) {
      m.status = "down";
      const what = def.type === "tls" ? "certificate is invalid or unreachable" : def.type === "domain" ? "domain registration lookup failed or has lapsed" : "is not responding";
      const inc = { id: `inc_${now.toString(36)}_${def.id}`, monitors: [def.id], title: `${def.name || def.id} ${what}`, impact: "major", status: "investigating", auto: true, startedAt: m.firstFailAt, resolvedAt: null, updates: [{ at: now, status: "investigating", message: `${m.streakFail} checks in a row failed: ${m.lastError}` }] };
      pushIncident(state, inc);
      events.push({ type: "down", monitor: def, incident: inc });
    }
  }
  return events;
}

// Record the expiry date a tls/domain check found. Returns an "expiring" event the first time
// days-left drops to or below each warnDays threshold, and one "renewed" event when it climbs
// back above the largest one. Never touches uptime: a certificate with 5 days left still serves.
export function recordExpiry(state, def, expiresAt, now) {
  const m = mon(state, def.id);
  const warn = [...(def.warnDays ?? EXPIRY_DEFAULTS.warnDays)].sort((a, b) => b - a);
  const daysLeft = Math.floor((expiresAt - now) / 86_400_000);
  const events = [];
  const renewed = m.expiresAt != null && expiresAt > m.expiresAt + 86_400_000;
  m.expiresAt = expiresAt; m.daysLeft = daysLeft;
  if (renewed || daysLeft > warn[0]) {
    if (m.warnedAt != null && daysLeft > warn[0]) events.push({ type: "renewed", monitor: def, daysLeft, expiresAt });
    m.warnedAt = null;
  }
  const due = warn.filter((w) => daysLeft <= w);
  const level = due.length ? Math.min(...due) : null;
  if (level !== null && (m.warnedAt == null || level < m.warnedAt)) { m.warnedAt = level; events.push({ type: "expiring", monitor: def, threshold: level, daysLeft, expiresAt }); }
  return events;
}

// Push (heartbeat) monitors: a ping must arrive within every intervalSec + graceSec.
export function recordPing(state, def, now) {
  mon(state, def.id).lastPingAt = now;
}
export function pushResult(state, def, now) {
  const m = mon(state, def.id);
  if (m.lastPingAt === null) return { ok: false, error: "no ping received yet" };
  const window = ((def.intervalSec ?? DEFAULTS.intervalSec) + (def.graceSec ?? DEFAULTS.graceSec)) * 1000;
  return now - m.lastPingAt <= window ? { ok: true } : { ok: false, error: `no ping for ${Math.round((now - m.lastPingAt) / 1000)}s` };
}

export function createIncident(state, { title, impact = "minor", message = "", monitors = [], now }) {
  if (!title || !String(title).trim()) throw new Error("title required");
  if (!IMPACTS.includes(impact)) throw new Error(`impact must be one of ${IMPACTS.join(", ")}`);
  const inc = { id: `inc_${now.toString(36)}_m${state.incidents.length}`, monitors, title: String(title).slice(0, 140), impact, status: "investigating", auto: false, startedAt: now, resolvedAt: null, updates: [{ at: now, status: "investigating", message: String(message).slice(0, 2000) }] };
  pushIncident(state, inc);
  return inc;
}

export function addUpdate(state, id, { status, message = "", now }) {
  const inc = state.incidents.find((i) => i.id === id);
  if (!inc) throw Object.assign(new Error("no such incident"), { status: 404 });
  if (!INCIDENT_STATUSES.includes(status)) throw new Error(`status must be one of ${INCIDENT_STATUSES.join(", ")}`);
  inc.status = status;
  inc.updates.push({ at: now, status, message: String(message).slice(0, 2000) });
  inc.resolvedAt = status === "resolved" ? now : null;
  return inc;
}

export function scheduleMaintenance(state, { title, startsAt, endsAt, monitors = [] }) {
  if (!title || !Number.isFinite(startsAt) || !Number.isFinite(endsAt) || endsAt <= startsAt) throw new Error("title, startsAt and a later endsAt (epoch ms) required");
  const m = { id: `mnt_${startsAt.toString(36)}`, title: String(title).slice(0, 140), startsAt, endsAt, monitors };
  state.maintenance.push(m);
  state.maintenance = state.maintenance.slice(-50);
  return m;
}

export function uptimePct(m, days, now) {
  if (!m) return null;
  let ok = 0, total = 0;
  for (let i = 0; i < days; i++) {
    const d = m.days[dayKey(now - i * 86_400_000)];
    if (d) { ok += d.ok; total += d.total; }
  }
  return total ? (ok / total) * 100 : null;
}

export const fmtPct = (p) => (p === null ? "n/a" : p >= 99.995 ? "100%" : `${(Math.floor(p * 100) / 100).toFixed(2)}%`);

// Bars for the last n days, oldest first.
export function dayBars(m, n, now) {
  return Array.from({ length: n }, (_, k) => {
    const date = dayKey(now - (n - 1 - k) * 86_400_000);
    const d = m?.days[date];
    const pct = d && d.total ? (d.ok / d.total) * 100 : null;
    return { date, pct, level: pct === null ? "none" : pct >= 99.9 ? "ok" : pct >= 95 ? "minor" : "major" };
  });
}

export function overall(state, defs, now) {
  const live = defs.filter((d) => !inMaintenance(state, d.id, now));
  if (defs.length && !live.length) return "maintenance";
  const down = live.filter((d) => state.monitors[d.id]?.status === "down").length;
  if (down && down === live.length) return "major_outage";
  if (down) return "partial_outage";
  const open = state.incidents.filter((i) => !i.resolvedAt && !i.auto);
  if (open.some((i) => i.impact === "major")) return "partial_outage";
  if (open.length) return "degraded";
  if (defs.length && live.every((d) => (state.monitors[d.id]?.status ?? "unknown") === "unknown")) return "unknown";
  return "operational";
}

export const LABELS = { operational: "All systems operational", degraded: "Degraded performance", partial_outage: "Partial outage", major_outage: "Major outage", maintenance: "Scheduled maintenance", unknown: "Waiting for the first checks" };
export const COLORS = { operational: "#1a7f37", degraded: "#9a6700", partial_outage: "#c2410c", major_outage: "#cf222e", maintenance: "#0969da", unknown: "#6e7781" };

// How much downtime an availability target allows, in seconds.
export function allowedDowntimeSec(targetPct, periodDays) {
  if (!(targetPct > 0 && targetPct <= 100) || !(periodDays > 0)) return null;
  return (1 - targetPct / 100) * periodDays * 86400;
}
export function humanDuration(sec) {
  if (sec === null) return "n/a";
  sec = Math.round(sec);
  if (sec < 60) return `${sec}s`;
  if (sec < 3600) return `${Math.floor(sec / 60)}m ${sec % 60}s`;
  if (sec < 86400) return `${Math.floor(sec / 3600)}h ${Math.floor((sec % 3600) / 60)}m`;
  return `${Math.floor(sec / 86400)}d ${Math.floor((sec % 86400) / 3600)}h`;
}

render.mjs.text:
// Server-rendered public pages: HTML status page, JSON, Atom feed, SVG badge. No browser JS needed.
import { overall, LABELS, COLORS, uptimePct, fmtPct, dayBars, inMaintenance } from "./monitor.mjs";

export const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const iso = (ms) => new Date(ms).toISOString();
const LEVEL_COLOR = { ok: "#2da44e", minor: "#bf8700", major: "#cf222e", none: "#d0d7de" };

export function statusJson(state, defs, cfg, now) {
  const st = overall(state, defs, now);
  return {
    page: { name: cfg.title, updatedAt: iso(now) },
    status: { indicator: st, description: LABELS[st] },
    components: defs.map((d) => {
      const m = state.monitors[d.id];
      return { id: d.id, name: d.name || d.id, status: inMaintenance(state, d.id, now) ? "maintenance" : m?.status ?? "unknown", uptime30d: uptimePct(m, 30, now), uptime90d: uptimePct(m, 90, now), responseMs: m?.lastMs ?? null, ...(m?.expiresAt ? { type: d.type, expiresAt: iso(m.expiresAt), daysLeft: Math.floor((m.expiresAt - now) / 86_400_000) } : {}) };
    }),
    incidents: state.incidents.slice(0, 20).map((i) => ({ id: i.id, title: i.title, status: i.status, impact: i.impact, startedAt: iso(i.startedAt), resolvedAt: i.resolvedAt ? iso(i.resolvedAt) : null, updates: i.updates.map((u) => ({ at: iso(u.at), status: u.status, message: u.message })) })),
    maintenance: state.maintenance.filter((m) => m.endsAt > now).map((m) => ({ id: m.id, title: m.title, startsAt: iso(m.startsAt), endsAt: iso(m.endsAt) })),
  };
}

export function badgeSvg(label, value, color) {
  const w1 = 6 * label.length + 14, w2 = 6 * value.length + 14;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w1 + w2}" height="20" role="img" aria-label="${esc(label)}: ${esc(value)}"><rect width="${w1}" height="20" fill="#555"/><rect x="${w1}" width="${w2}" height="20" fill="${color}"/><g fill="#fff" font-family="Verdana,sans-serif" font-size="11" text-anchor="middle"><text x="${w1 / 2}" y="14">${esc(label)}</text><text x="${w1 + w2 / 2}" y="14">${esc(value)}</text></g></svg>`;
}

export function atomFeed(state, cfg, now) {
  const entries = state.incidents.slice(0, 30).map((i) => {
    const last = i.updates[i.updates.length - 1];
    return `<entry><id>${esc(cfg.publicUrl)}#${esc(i.id)}</id><title>${esc(`[${i.status}] ${i.title}`)}</title><updated>${iso(last.at)}</updated><published>${iso(i.startedAt)}</published><content type="text">${esc(i.updates.map((u) => `${iso(u.at)} ${u.status}: ${u.message}`).join("\n"))}</content></entry>`;
  });
  return `<?xml version="1.0" encoding="utf-8"?><feed xmlns="http://www.w3.org/2005/Atom"><id>${esc(cfg.publicUrl)}</id><title>${esc(cfg.title)} incidents</title><updated>${iso(state.incidents[0] ? state.incidents[0].updates.at(-1).at : now)}</updated><link href="${esc(cfg.publicUrl)}"/>${entries.join("")}</feed>`;
}

const SHELL_CSS = ":root{font:16px system-ui,sans-serif;color:#1f2328;background:#f6f8fa}body{max-width:560px;margin:auto;padding:24px}button,input{font:inherit;padding:8px 10px;border-radius:6px;border:1px solid #8c959f}button{background:#0969da;color:#fff;border-color:#0969da;cursor:pointer}a{color:#0550ae}";
export function messagePage(cfg, title, bodyHtml) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)} - ${esc(cfg.title)}</title><style>${SHELL_CSS}</style></head><body><h1>${esc(title)}</h1>${bodyHtml}<p><a href="/">Back to ${esc(cfg.title)} status</a></p></body></html>`;
}

export function statusPage(state, defs, cfg, now) {
  const st = overall(state, defs, now);
  const rows = defs.map((d) => {
    const m = state.monitors[d.id];
    const status = inMaintenance(state, d.id, now) ? "maintenance" : m?.status ?? "unknown";
    const bars = dayBars(m, 90, now).map((b) => `<i title="${esc(b.date)}: ${b.pct === null ? "no data" : fmtPct(b.pct)}" style="background:${LEVEL_COLOR[b.level]}"></i>`).join("");
    const word = { up: "Operational", down: "Down", maintenance: "Maintenance", unknown: "Pending" }[status];
    return `<section class="c"><div class="h"><strong>${esc(d.name || d.id)}</strong><span style="color:${status === "up" ? COLORS.operational : status === "down" ? COLORS.major_outage : status === "maintenance" ? COLORS.maintenance : COLORS.unknown}">${word}</span></div><div class="bars" role="img" aria-label="Last 90 days of uptime">${bars}</div><div class="f"><span>90 days ago</span><span>${fmtPct(uptimePct(m, 90, now))} uptime</span><span>Today</span></div>${m?.expiresAt ? `<div class="f"><span>${d.type === "domain" ? "Registered until" : "Certificate valid until"} ${esc(iso(m.expiresAt).slice(0, 10))}</span><span>${Math.max(0, Math.floor((m.expiresAt - now) / 86_400_000))} days left</span></div>` : ""}</section>`;
  }).join("");
  const upcoming = state.maintenance.filter((m) => m.endsAt > now).map((m) => `<p class="m"><strong>${esc(m.title)}</strong><br>${iso(m.startsAt)} to ${iso(m.endsAt)}</p>`).join("");
  const incidents = state.incidents.slice(0, 15).map((i) => `<article class="i"><h3>${esc(i.title)} <small>${esc(i.status)}</small></h3>${[...i.updates].reverse().map((u) => `<p><strong>${esc(u.status)}</strong> <time>${iso(u.at)}</time><br>${esc(u.message)}</p>`).join("")}</article>`).join("") || "<p>No incidents reported.</p>";
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(cfg.title)} status</title><meta name="description" content="${esc(LABELS[st])} - live status and 90-day uptime for ${esc(cfg.title)}."><link rel="alternate" type="application/atom+xml" href="/feed.xml"><style>:root{font:16px system-ui,sans-serif;color:#1f2328;background:#f6f8fa}body{max-width:760px;margin:auto;padding:24px}h1{font-size:1.5rem}.banner{background:${COLORS[st]};color:#fff;padding:18px;border-radius:10px;font-size:1.2rem;font-weight:700;margin:16px 0}.c,.i,.m{background:#fff;border:1px solid #d0d7de;border-radius:10px;padding:14px;margin:12px 0}.h{display:flex;justify-content:space-between}.bars{display:flex;gap:2px;height:30px;margin:10px 0 4px}.bars i{flex:1;border-radius:2px}.f{display:flex;justify-content:space-between;font-size:.8rem;color:#57606a}h3 small{font-weight:400;color:#57606a}time{color:#57606a;font-size:.85rem}form.sub{background:#fff;border:1px solid #d0d7de;border-radius:10px;padding:14px;margin:12px 0}form.sub input[type=email]{min-width:16em}button{background:#0969da;color:#fff;border:1px solid #0969da;border-radius:6px;padding:8px 12px;font:inherit;cursor:pointer}footer{font-size:.8rem;color:#57606a;margin-top:28px}</style></head><body><h1>${esc(cfg.title)}</h1><div class="banner" role="status">${esc(LABELS[st])}</div>${rows}${upcoming ? `<h2>Scheduled maintenance</h2>${upcoming}` : ""}<h2>Incidents</h2>${incidents}${cfg.emailEnabled ? `<form class="sub" method="post" action="/subscribe"><h2>Get updates by email</h2><label for="se">Email address</label> <input id="se" name="email" type="email" required autocomplete="email"> <input name="website" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-9999px"> <button type="submit">Subscribe</button><p><small>You get a confirmation email first. Incident and maintenance notices only; one-click unsubscribe in every email.</small></p></form>` : ""}<footer>Updated ${iso(now)} &middot; <a href="/feed.xml">Atom feed</a> &middot; <a href="/api/status.json">JSON</a> &middot; Powered by <a href="https://github.com/Duncan-Haywood/fp-monorepo/tree/main/ventures/status-keeper">status-keeper</a> (free, MIT; no uptime guarantee)</footer></body></html>`;
}

server.mjs.text:
#!/usr/bin/env node
// Self-hosted uptime monitor + public status page. Zero dependencies, state in one JSON file.
//   ADMIN_KEY=... TITLE="Acme" MONITORS_JSON='[{"id":"site","name":"Website","url":"https://example.com"}]' node server.mjs
// GET /            the public status page (90-day bars, incidents, maintenance)
// GET /api/status.json, /feed.xml, /badge.svg   for machines, feed readers and READMEs
// POST /ping/<id>?token=...   heartbeat for cron jobs (monitors of type "push")
// POST /subscribe, GET /confirm?t=, GET|POST /unsubscribe?t=   email notices (only when RESEND_API_KEY + MAIL_FROM are set)
// POST /v1/incidents, /v1/incidents/<id>/updates, /v1/maintenance   admin API (Bearer ADMIN_KEY)
import http from "node:http";
import fs from "node:fs";
import { timingSafeEqual } from "node:crypto";
import { DEFAULTS, EXPIRY_DEFAULTS, EXPIRY_TYPES, recordExpiry, newState, recordCheck, recordPing, pushResult, createIncident, addUpdate, scheduleMaintenance, overall, LABELS, COLORS, humanDuration } from "./monitor.mjs";
import { statusPage, statusJson, atomFeed, badgeSvg, messagePage } from "./render.mjs";
import { checkTls, checkDomain } from "./certs.mjs";
import { subscribe, confirm, unsubscribe, activeCount, confirmationMail, notifyAll } from "./subscribers.mjs";

const env = process.env;

export function parseMonitors(json) {
  const list = JSON.parse(json || "[]");
  if (!Array.isArray(list) || !list.length) throw new Error("MONITORS_JSON must be a non-empty array");
  const seen = new Set();
  return list.map((m) => {
    if (!/^[a-z0-9][a-z0-9_-]{0,40}$/.test(m.id || "")) throw new Error(`bad monitor id: ${m.id}`);
    if (seen.has(m.id)) throw new Error(`duplicate monitor: ${m.id}`);
    seen.add(m.id);
    const type = m.type || "http";
    if (EXPIRY_TYPES.includes(type)) {
      const target = type === "tls" ? m.host : m.domain;
      if (!/^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$/i.test(target || "") || !String(target).includes(".")) throw new Error(`monitor ${m.id}: ${type === "tls" ? "host" : "domain"} must be a DNS name`);
      if (m.warnDays !== undefined && !(Array.isArray(m.warnDays) && m.warnDays.length && m.warnDays.every((d) => Number.isInteger(d) && d > 0 && d <= 365))) throw new Error(`monitor ${m.id}: warnDays must be a list of whole days, 1 to 365`);
      if (type === "tls" && m.port !== undefined && !(Number.isInteger(m.port) && m.port > 0 && m.port < 65536)) throw new Error(`monitor ${m.id}: bad port`);
      return { ...DEFAULTS, ...EXPIRY_DEFAULTS, ...m, type };
    }
    if (type === "http" && !/^https?:\/\//.test(m.url || "")) throw new Error(`monitor ${m.id}: url must be http(s)`);
    if (type === "push" && !(m.token && String(m.token).length >= 12)) throw new Error(`monitor ${m.id}: push monitors need a token of at least 12 characters`);
    if (!["http", "push"].includes(type)) throw new Error(`monitor ${m.id}: type must be http, push, tls or domain`);
    return { ...DEFAULTS, ...m, type };
  });
}

const safeEq = (a, b) => { const x = Buffer.from(String(a)), y = Buffer.from(String(b)); return x.length === y.length && timingSafeEqual(x, y); };
const bearerOk = (req, key) => Boolean(key) && safeEq(req.headers.authorization || "", `Bearer ${key}`);

const readJson = (req) => new Promise((resolve, reject) => {
  let size = 0; const chunks = [];
  req.on("data", (c) => { size += c.length; if (size > 100_000) { reject(Object.assign(new Error("too large"), { status: 413 })); req.destroy(); } else chunks.push(c); });
  req.on("end", () => { try { resolve(chunks.length ? JSON.parse(Buffer.concat(chunks).toString()) : {}); } catch { reject(Object.assign(new Error("invalid JSON"), { status: 400 })); } });
  req.on("error", reject);
});

// Form posts are small and urlencoded; JSON is accepted too.
const readBody = async (req) => {
  if (!(req.headers["content-type"] || "").includes("application/x-www-form-urlencoded")) return readJson(req);
  let size = 0; const chunks = [];
  for await (const c of req) { size += c.length; if (size > 10_000) throw Object.assign(new Error("too large"), { status: 413 }); chunks.push(c); }
  return Object.fromEntries(new URLSearchParams(Buffer.concat(chunks).toString()));
};

// cfg: {state, save, monitors, adminKey, title, publicUrl, now, sendEmail?}
// sendEmail({to, subject, text, headers?}) enables subscriptions; leave it out and the routes 404.
export function handler(cfg) {
  const now = cfg.now || Date.now;
  const meta = { title: cfg.title || "Status", publicUrl: cfg.publicUrl || "/", emailEnabled: Boolean(cfg.sendEmail) };
  const notify = (event) => cfg.sendEmail ? notifyAll(cfg.state, event, meta, cfg.sendEmail) : Promise.resolve();
  const byId = Object.fromEntries(cfg.monitors.map((m) => [m.id, m]));
  return async (req, res) => {
    const url = new URL(req.url, "http://x");
    const send = (code, body, type = "application/json", extra = {}) => {
      res.writeHead(code, { "content-type": type, "x-content-type-options": "nosniff", ...extra });
      res.end(typeof body === "string" ? body : JSON.stringify(body, null, 2));
    };
    try {
      const t = now();
      if (url.pathname === "/healthz") return send(200, "ok\n", "text/plain");
      if (req.method === "GET" && url.pathname === "/") return send(200, statusPage(cfg.state, cfg.monitors, meta, t), "text/html; charset=utf-8", { "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'", "cache-control": "public, max-age=30" });
      if (req.method === "GET" && url.pathname === "/api/status.json") return send(200, statusJson(cfg.state, cfg.monitors, meta, t), "application/json", { "access-control-allow-origin": "*", "cache-control": "public, max-age=30" });
      if (req.method === "GET" && url.pathname === "/feed.xml") return send(200, atomFeed(cfg.state, meta, t), "application/atom+xml; charset=utf-8");
      if (req.method === "GET" && url.pathname === "/badge.svg") { const st = overall(cfg.state, cfg.monitors, t); return send(200, badgeSvg("status", LABELS[st].toLowerCase(), COLORS[st]), "image/svg+xml", { "cache-control": "public, max-age=60" }); }
      if (cfg.sendEmail && ["/subscribe", "/confirm", "/unsubscribe"].includes(url.pathname)) {
        const html = (code, title, body) => send(code, messagePage(meta, title, body), "text/html; charset=utf-8", { "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'", "cache-control": "no-store", "referrer-policy": "no-referrer" });
        const token = url.searchParams.get("t") || "";
        if (req.method === "POST" && url.pathname === "/subscribe") {
          const b = await readBody(req);
          const r = b.website ? { action: "invalid" } : subscribe(cfg.state, String(b.email || ""), t); // "website" is a honeypot field
          if (r.action === "invalid" && !b.website) return html(400, "That address does not look right", "<p>Check the email address and <a href=\"/\">try again</a>.</p>");
          if (r.action === "full") return html(503, "Subscriptions are full", "<p>This page cannot take more subscribers right now.</p>");
          if (r.action === "confirm") { cfg.save(); await cfg.sendEmail(confirmationMail(r.sub, meta)).catch((e) => console.error("confirmation failed:", e.message)); }
          // Same answer whether or not the address was new, so the form cannot be used to probe who subscribes.
          return html(202, "Check your inbox", "<p>If that address can be subscribed, we sent a confirmation link. Nothing is sent until you click it.</p>");
        }
        if (req.method === "GET" && url.pathname === "/confirm") {
          const s = confirm(cfg.state, token, t);
          if (!s) return html(404, "Link expired", "<p>This confirmation link is invalid or has expired. <a href=\"/\">Subscribe again</a>.</p>");
          cfg.save(); return html(200, "You are subscribed", "<p>You will get an email when an incident opens, updates or resolves, and before scheduled maintenance. Every email has an unsubscribe link.</p>");
        }
        if (url.pathname === "/unsubscribe" && req.method === "GET") return html(200, "Unsubscribe", `<form method="post" action="/unsubscribe?t=${encodeURIComponent(token)}"><p>Stop status emails to this address?</p><button type="submit">Unsubscribe</button></form>`);
        if (url.pathname === "/unsubscribe" && req.method === "POST") {
          const gone = unsubscribe(cfg.state, token);
          if (gone) cfg.save();
          return html(200, "Unsubscribed", "<p>You will not get any more status emails.</p>");
        }
      }
      if (req.method === "POST" && url.pathname.startsWith("/ping/")) {
        const def = byId[url.pathname.slice(6)];
        if (!def || def.type !== "push" || !safeEq(url.searchParams.get("token") || "", def.token)) return send(404, "not found\n", "text/plain");
        recordPing(cfg.state, def, t); cfg.save();
        return send(200, "ok\n", "text/plain");
      }
      if (url.pathname.startsWith("/v1/")) {
        if (!bearerOk(req, cfg.adminKey)) return send(401, "admin key required\n", "text/plain");
        const parts = url.pathname.slice(4).split("/");
        try {
          if (req.method === "POST" && parts[0] === "incidents" && !parts[1]) { const inc = createIncident(cfg.state, { ...(await readJson(req)), now: t }); cfg.save(); await notify({ kind: "incident", incident: inc }); return send(201, inc); }
          if (req.method === "POST" && parts[0] === "incidents" && parts[2] === "updates") { const inc = addUpdate(cfg.state, parts[1], { ...(await readJson(req)), now: t }); cfg.save(); await notify({ kind: inc.status === "resolved" ? "resolved" : "update", incident: inc }); return send(200, inc); }
          if (req.method === "POST" && parts[0] === "maintenance") { const b = await readJson(req); const m = scheduleMaintenance(cfg.state, { ...b, startsAt: Date.parse(b.startsAt), endsAt: Date.parse(b.endsAt) }); cfg.save(); await notify({ kind: "maintenance", maintenance: m }); return send(201, m); }
          if (req.method === "GET" && parts[0] === "subscribers") return send(200, { active: activeCount(cfg.state), total: (cfg.state.subscribers || []).length });
        } catch (e) { return send(e.status || 400, `${e.message}\n`, "text/plain"); }
      }
      return send(404, "not found\n", "text/plain");
    } catch (e) {
      console.error("request failed:", e.message);
      return send(e.status || 500, "error\n", "text/plain");
    }
  };
}

export async function checkHttp(def, doFetch = fetch) {
  const started = Date.now();
  try {
    const res = await doFetch(def.url, { method: def.method || "GET", redirect: "manual", headers: { "user-agent": "status-keeper/1" }, signal: AbortSignal.timeout(def.timeoutMs) });
    const ms = Date.now() - started;
    const okStatus = Array.isArray(def.expectStatus) ? def.expectStatus.includes(res.status) : res.status < 400;
    if (!okStatus) return { ok: false, ms, error: `HTTP ${res.status}` };
    if (def.contains) { const text = (await res.text()).slice(0, 1_000_000); if (!text.includes(def.contains)) return { ok: false, ms, error: `response did not contain "${def.contains}"` }; }
    return { ok: true, ms };
  } catch (e) {
    return { ok: false, ms: Date.now() - started, error: String(e.name === "TimeoutError" ? `timed out after ${def.timeoutMs}ms` : e.cause?.code || e.message || e).slice(0, 200) };
  }
}

// One pass over every monitor that is due. deps: {fetch, alert, notify(event)}. Returns true if state changed.
export async function tick(state, defs, now, deps = {}) {
  let changed = false;
  await Promise.all(defs.map(async (def) => {
    const m = state.monitors[def.id];
    if (m?.lastCheckAt && now - m.lastCheckAt < def.intervalSec * 1000) return;
    let result;
    if (def.type === "push") { if (!m || m.lastPingAt === null) return; result = pushResult(state, def, now); }
    else if (def.type === "tls") result = await checkTls(def, deps.connect, now);
    else if (def.type === "domain") result = await checkDomain(def, deps.fetch, now);
    else result = await checkHttp(def, deps.fetch);
    changed = true;
    if (result.expiresAt) {
      for (const ev of recordExpiry(state, def, result.expiresAt, now)) {
        const what = def.type === "tls" ? "certificate" : "domain registration";
        const day = new Date(ev.expiresAt).toISOString().slice(0, 10);
        if (deps.alert) await deps.alert(ev.type === "expiring"
          ? `status-keeper: ${def.name || def.id} ${what} expires in ${Math.max(ev.daysLeft, 0)} day(s) (${day})`
          : `status-keeper: ${def.name || def.id} ${what} renewed, now valid until ${day}`).catch(() => {});
      }
    }
    for (const ev of recordCheck(state, def, result, now)) {
      if (deps.notify) await deps.notify({ kind: ev.type === "down" ? "incident" : "resolved", incident: ev.incident }).catch(() => {});
      if (!deps.alert) continue;
      await deps.alert(ev.type === "down"
        ? `status-keeper: ${def.name || def.id} is DOWN (${ev.incident.updates[0].message})`
        : `status-keeper: ${def.name || def.id} recovered after ${humanDuration(ev.downMs / 1000)}`);
    }
  }));
  return changed;
}

function readState(path) {
  try { return JSON.parse(fs.readFileSync(path, "utf8")); } catch (e) { if (e.code === "ENOENT") return newState(); throw e; }
}

async function alert(text) {
  console.log(text);
  if (env.ALERT_WEBHOOK_URL) await fetch(env.ALERT_WEBHOOK_URL, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ text, content: text }) }).catch(() => {});
}

// Resend's HTTP API: one POST per message, no SMTP and no dependency.
async function sendResend(msg) {
  const res = await fetch("https://api.resend.com/emails", {
    method: "POST", headers: { authorization: `Bearer ${env.RESEND_API_KEY}`, "content-type": "application/json" },
    body: JSON.stringify({ from: env.MAIL_FROM, to: [msg.to], subject: msg.subject, text: msg.text, headers: msg.headers }),
  });
  if (!res.ok) throw new Error(`resend ${res.status}`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  if (!env.ADMIN_KEY) { console.error("missing env: ADMIN_KEY"); process.exit(1); }
  let monitors;
  try { monitors = parseMonitors(env.MONITORS_JSON); } catch (e) { console.error(`MONITORS_JSON: ${e.message}`); process.exit(1); }
  const statePath = env.STATE || "state.json";
  const state = readState(statePath);
  const save = () => { fs.writeFileSync(`${statePath}.tmp`, JSON.stringify(state)); fs.renameSync(`${statePath}.tmp`, statePath); };
  if (Boolean(env.RESEND_API_KEY) !== Boolean(env.MAIL_FROM)) { console.error("email notices need both RESEND_API_KEY and MAIL_FROM"); process.exit(1); }
  const sendEmail = env.RESEND_API_KEY ? sendResend : undefined;
  if (sendEmail && !/^https:\/\//.test(env.PUBLIC_URL || "")) { console.error("email notices need PUBLIC_URL (https) so links in emails work"); process.exit(1); }
  const meta = { title: env.TITLE || "Status", publicUrl: env.PUBLIC_URL || "/" };
  const notify = sendEmail ? (event) => notifyAll(state, event, meta, sendEmail) : undefined;
  let busy = false;
  setInterval(async () => {
    if (busy) return;
    busy = true;
    try { if (await tick(state, monitors, Date.now(), { alert, notify })) save(); } catch (e) { console.error("tick failed:", e.message); } finally { busy = false; }
  }, 5000).unref?.();
  http.createServer(handler({ state, save, monitors, adminKey: env.ADMIN_KEY, title: env.TITLE, publicUrl: env.PUBLIC_URL, sendEmail })).listen(Number(env.PORT || 8080), () =>
    console.log(`status-keeper on :${env.PORT || 8080} watching ${monitors.length} monitor(s)`));
}

subscribers.mjs.text:
// Email subscriptions for the status page: double opt-in, one-click unsubscribe, notices on
// incidents and maintenance. Server-side only (uses node:crypto). Sending is injected, so the
// logic runs under test with no network; server.mjs wires it to Resend when keys are set.
import { randomBytes } from "node:crypto";

export const MAX_SUBSCRIBERS = 5000;
export const PENDING_TTL_MS = 48 * 3600_000;
export const RESEND_COOLDOWN_MS = 3600_000;
export const CONFIRM_MAILS_PER_HOUR = 30; // caps how many strangers a bot can make us email

export const validEmail = (e) => typeof e === "string" && e.length <= 254 && /^[^\s@<>"',;]+@[^\s@<>"',;]+\.[^\s@<>"',;]{2,}$/.test(e);
const norm = (e) => String(e).trim().toLowerCase();
const subs = (state) => (state.subscribers ||= []);
const newToken = () => randomBytes(18).toString("base64url");

// Returns {action:"confirm"|"already"|"cooldown"|"full"|"rate"|"invalid", sub?}. "already" and
// "cooldown" look identical to the caller of the HTTP API, so the form cannot probe who is subscribed.
export function subscribe(state, rawEmail, now, token = newToken()) {
  if (!validEmail(String(rawEmail).trim())) return { action: "invalid" };
  const email = norm(rawEmail);
  prune(state, now);
  const list = subs(state);
  const existing = list.find((s) => s.email === email);
  if (existing?.status === "active") return { action: "already", sub: existing };
  const recent = (state.confirmSent ||= []).filter((t) => now - t < 3600_000);
  state.confirmSent = recent;
  if (existing) {
    if (now - existing.createdAt < RESEND_COOLDOWN_MS) return { action: "cooldown", sub: existing };
    if (recent.length >= CONFIRM_MAILS_PER_HOUR) return { action: "rate" };
    existing.createdAt = now; recent.push(now);
    return { action: "confirm", sub: existing };
  }
  if (list.length >= MAX_SUBSCRIBERS) return { action: "full" };
  if (recent.length >= CONFIRM_MAILS_PER_HOUR) return { action: "rate" };
  const sub = { email, status: "pending", token, createdAt: now, confirmedAt: null };
  list.push(sub); recent.push(now);
  return { action: "confirm", sub };
}

export function prune(state, now) {
  const list = subs(state);
  state.subscribers = list.filter((s) => s.status === "active" || now - s.createdAt < PENDING_TTL_MS);
}

export function confirm(state, token, now) {
  const s = subs(state).find((x) => x.token === token && token);
  if (!s) return null;
  if (s.status === "pending") {
    if (now - s.createdAt >= PENDING_TTL_MS) return null;
    s.status = "active"; s.confirmedAt = now;
  }
  return s;
}

export function unsubscribe(state, token) {
  const list = subs(state);
  const i = list.findIndex((x) => x.token === token && token);
  if (i < 0) return null;
  return list.splice(i, 1)[0];
}

export const activeCount = (state) => subs(state).filter((s) => s.status === "active").length;

const link = (base, path, token) => `${base.replace(/\/$/, "")}${path}?t=${encodeURIComponent(token)}`;

export function confirmationMail(sub, meta) {
  return {
    to: sub.email,
    subject: `Confirm your subscription to ${meta.title} status updates`,
    text: `Someone (hopefully you) asked for ${meta.title} status updates at this address.\n\nConfirm: ${link(meta.publicUrl, "/confirm", sub.token)}\n\nIf this was not you, ignore this email and nothing will be sent. The request expires in 48 hours.\n`,
  };
}

// event: {kind:"incident"|"update"|"resolved"|"maintenance", incident?, maintenance?}
export function noticeMail(event, sub, meta) {
  const unsub = link(meta.publicUrl, "/unsubscribe", sub.token);
  let subject, body;
  if (event.kind === "maintenance") {
    const m = event.maintenance;
    subject = `[${meta.title}] Scheduled maintenance: ${m.title}`;
    body = `${m.title}\nFrom ${new Date(m.startsAt).toISOString()} to ${new Date(m.endsAt).toISOString()}.\nChecks during this window do not count against uptime.`;
  } else {
    const i = event.incident, u = i.updates[i.updates.length - 1];
    subject = `[${meta.title}] ${event.kind === "resolved" ? "Resolved" : i.status === "investigating" && event.kind === "incident" ? "Incident" : "Update"}: ${i.title}`;
    body = `${i.title}\nStatus: ${u.status}\n\n${u.message || "(no details yet)"}`;
  }
  return {
    to: sub.email, subject,
    text: `${body}\n\nLive status: ${meta.publicUrl}\nUnsubscribe: ${unsub}\n`,
    headers: { "List-Unsubscribe": `<${unsub}>`, "List-Unsubscribe-Post": "List-Unsubscribe=One-Click" },
  };
}

// Send one notice to every active subscriber. Never throws; returns {sent, failed}.
export async function notifyAll(state, event, meta, send) {
  let sent = 0, failed = 0;
  for (const sub of subs(state).filter((s) => s.status === "active")) {
    try { await send(noticeMail(event, sub, meta)); sent++; } catch { failed++; }
  }
  return { sent, failed };
}

